    private suspend fun postSafely(item: NotificationItem, refresh: Boolean = false): PostResult = try {
        if (refresh) poster.refresh(item) else poster.post(item)
    } catch (cancelled: kotlinx.coroutines.CancellationException) {
        throw cancelled
    } catch (_: Exception) {
        PostResult.Failed("notification_post_failed")
    }

    companion object { const val MAX_EVENT_KEYS = 4096; const val MAX_BATCH_ATTEMPTS = 256 }
}
